<?php
namespace LibreNMS\Plugins\InterfaceAlertPolicyManager\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Routing\Controller; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Http\Requests\PolicyRequest; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Models\Policy; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Models\Schedule; use LibreNMS\Plugins\InterfaceAlertPolicyManager\Services\AuditService;
class PolicyController extends Controller { public function index(){return view('iapm::policies.index',['policies'=>Policy::withCount(['assignments','actions'])->orderByDesc('priority')->paginate(50)]);} public function create(){return view('iapm::policies.form',['policy'=>new Policy,'schedules'=>Schedule::where('enabled',true)->orderBy('name')->get()]);} public function store(PolicyRequest $r,AuditService $audit){$p=Policy::create($r->validated()+['created_by'=>$r->user()->getAuthIdentifier(),'updated_by'=>$r->user()->getAuthIdentifier()]);$audit->record($r,'created','policy',$p,null,$p->toArray());return redirect()->route('iapm.policies.edit',$p)->with('status','Policy created.');} public function edit(Policy $policy){return view('iapm::policies.form',['policy'=>$policy,'schedules'=>Schedule::where('enabled',true)->orderBy('name')->get(),'otherPolicies'=>Policy::whereKeyNot($policy->id)->orderBy('name')->get(),'openIncidentCount'=>$policy->incidents()->where('state','!=','recovered')->count()]);} public function update(PolicyRequest $r,Policy $policy,AuditService $audit){$before=$policy->toArray();$policy->update($r->validated()+['updated_by'=>$r->user()->getAuthIdentifier()]);$audit->record($r,'updated','policy',$policy,$before,$policy->fresh()->toArray());return back()->with('status','Policy updated.');} public function destroy(Request $r,Policy $policy,AuditService $audit){abort_unless($r->user()->can('manage iapm policies'),403);$data=$r->validate(['migrate_to'=>['nullable','different:'.$policy->id,'exists:iapm_policies,id']]);$openIncidents=$policy->incidents()->where('state','!=','recovered');if($openIncidents->exists()){if(empty($data['migrate_to']))return back()->withErrors('Policy has active incidents. Choose another policy to migrate them to before deleting.');\Illuminate\Support\Facades\DB::transaction(function()use($openIncidents,$data,$r){foreach($openIncidents->get() as $incident){$incident->update(['policy_id'=>$data['migrate_to']]);$incident->events()->create(['event_type'=>'policy_changed','event_message'=>'Incident migrated to another policy before its policy was deleted.','event_data'=>['to_policy_id'=>(int)$data['migrate_to']],'actor_user_id'=>$r->user()->getAuthIdentifier()]);}});}$before=$policy->toArray();$policy->delete();$audit->record($r,'deleted','policy',$policy->id,$before,['migrated_incidents_to'=>$data['migrate_to']??null]);return redirect()->route('iapm.policies.index')->with('status','Policy deleted.');} public function clone(Request $r,Policy $policy,AuditService $audit){abort_unless($r->user()->can('manage iapm policies'),403);$copy=$policy->replicate();$copy->name=$policy->name.' (copy)';$copy->enabled=false;$copy->created_by=$r->user()->getAuthIdentifier();$copy->updated_by=$copy->created_by;$copy->save();foreach($policy->actions as $a){$new=$a->replicate();$new->policy_id=$copy->id;$new->save();}$audit->record($r,'cloned','policy',$copy,null,$copy->toArray());return redirect()->route('iapm.policies.edit',$copy);} }
